<?php
$section = $args['landing']['faq'] ?? [];
if (empty($section)) return;
?>
<section class="tht-landing-faq ads-clients" id="khach-hang" aria-labelledby="ads-clients-title"><div class="tht-landing-container mx-auto w-full max-w-7xl px-4 lg:px-8"><div class="ads-section-head" data-aos="fade-up"><p class="tht-landing-eyebrow"><?php echo e($section['eyebrow'] ?? ''); ?></p><h2 id="ads-clients-title"><?php echo e($section['title'] ?? ''); ?></h2></div><?php if (!empty($section['logos'])) : ?><div class="ads-client-logos" data-aos="fade-up"><?php foreach ($section['logos'] as $logo) : ?><span><img src="<?php echo e(\App\Support\Landing\LandingRegistry::assetUrl($logo)); ?>" alt="Logo khách hàng" width="180" height="70" loading="lazy"></span><?php endforeach; ?></div><?php endif; ?><h3 class="ads-review-title"><?php echo e($section['subtitle'] ?? ''); ?></h3><div class="ads-review-grid"><?php foreach (($section['items'] ?? []) as $index => $item) : ?><?php $image = (string) ($item['image'] ?? ''); ?><article class="ads-review-card" data-aos="fade-up" data-aos-delay="<?php echo e((string) (($index % 3) * 50)); ?>"><?php if ($image !== '') : ?><a class="ads-review-card__media glightbox" href="<?php echo e(\App\Support\Landing\LandingRegistry::assetUrl($image)); ?>" data-gallery="ads-feedback" data-title="<?php echo e($item['title']); ?>" aria-label="Xem chi tiết số liệu: <?php echo e($item['title']); ?>"><img src="<?php echo e(\App\Support\Landing\LandingRegistry::assetUrl($image)); ?>" alt="<?php echo e($item['title']); ?>" loading="lazy"><span><i class="fa-solid fa-chart-line" aria-hidden="true"></i>Xem chi tiết số liệu</span></a><?php else : ?><i class="fa-solid fa-quote-left" aria-hidden="true"></i><?php endif; ?><h4><?php echo e($item['title']); ?></h4><p><?php echo e($item['text']); ?></p></article><?php endforeach; ?></div></div></section>
